package com.vandorlabs.neoforge.gear;
import java.util.*;import com.vandorlabs.neoforge.navigation.observer.*;import com.vandorlabs.neoforge.transfer.NativeRawCell;import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.server.level.ServerLevel;
/** Previous observer aliases and upright tile fields remain strict, usable native snapshots. */
public final class NativeObserverSnapshotChecks {
 private static int checks;private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 public static void run(ServerLevel world,NativeObserverEntity source){for(var alias:Map.of("survey_dish_core","standalone_dish","sentinel_array_core","standalone_antenna").entrySet()){var block=NativeObserverBindings.CORES.get(alias.getValue());for(int meta=0;meta<8;meta++){var state=block.legacyState(meta);need(block.legacyMeta(state)==meta,"observer metadata roundtrip");var old=NbtUtils.writeBlockState(state);old.putString("Name","vandorlabs:"+alias.getKey());need(NativeGearSnapshot.decode(world.registryAccess(),old)==state,"old arm alias palette maps to standalone");need(NativeRawCell.decodePalette(world.registryAccess(),old,Map.of())==state,"old durable alias palette maps to standalone");var invalid=old.copy();invalid.getCompound("Properties").putString("missing_property","true");boolean rejected=false;try{NativeGearSnapshot.decode(world.registryAccess(),invalid);}catch(IllegalArgumentException expected){rejected=true;}need(rejected,"old alias keeps unknown property rejection");invalid=old.copy();invalid.putString("Unexpected","owned");rejected=false;try{NativeRawCell.decodePalette(world.registryAccess(),invalid,Map.of());}catch(IllegalArgumentException expected){rejected=true;}need(rejected,"old alias keeps unknown palette fields rejected");}}
 var raw=source.saveWithFullMetadata(world.registryAccess());raw.remove("ObserverInverted");var legacy=NativeGearSnapshot.stage(world.registryAccess(),new NativeGearSnapshot.Cell(source.getBlockPos(),source.getBlockState(),raw),false);need(legacy instanceof NativeObserverEntity observer&&!observer.inert()&&!observer.inverted()&&observer.key().equals(source.key()),"old upright NBT has one usable source identity");need(NativeGearSnapshot.same(raw,legacy.saveWithFullMetadata(world.registryAccess())),"legacy upright default normalized only for snapshot comparison");var wrong=raw.copy();wrong.putInt("ObserverInverted",0);boolean rejected=false;try{NativeGearSnapshot.stage(world.registryAccess(),new NativeGearSnapshot.Cell(source.getBlockPos(),source.getBlockState(),wrong),false);}catch(IllegalArgumentException expected){rejected=true;}need(rejected,"typed malformed inversion remains rejected");var p=source.cell(0,1,0);var part=world.getBlockEntity(p);need(part instanceof NativeObserverPartEntity,"formed real reserved part");var staged=NativeGearSnapshot.stage(world.registryAccess(),new NativeGearSnapshot.Cell(p,part.getBlockState(),part.saveWithFullMetadata(world.registryAccess())),false);need(staged instanceof NativeObserverPartEntity member&&!member.inert(),"fresh part factory loads exact valid arm snapshot");System.out.println("[vandorlabs][observer-runtime] compatibility PASS checks="+checks+" oldAliases/metadata/uprightNBT/strictNegatives/partFactory");}
 private NativeObserverSnapshotChecks(){}
}
